{
  "exit_criteria_version": "1.0",
  "intent": "general_science_question",
  "query": "How to make 10x PBS buffer",
  "judge_goal": "Stop only when the loop has enough grounded evidence to provide a specific, variant-scoped 10x PBS recipe, or a clearly limitation-qualified conventional recipe after a real retrieval attempt.",
  "required_retrieval_evidence": [
    {
      "criterion": "At least one external retrieval attempt exists",
      "evidence": "A logged literature-search query targeting '10x PBS', 'phosphate-buffered saline composition', 'PBS formulation', or an equivalent term, with returned results or an explicit no-result outcome."
    },
    {
      "criterion": "The retrieval is relevant to the chemistry of PBS",
      "evidence": "At least one retrieved source mentions PBS composition, phosphate-buffered saline formulation, or a directly equivalent 1x PBS recipe that can be scaled to 10x."
    }
  ],
  "stop_when": [
    {
      "criterion": "A citation-backed recipe is available",
      "evidence_required": [
        "A retrieved source gives either the exact 10x PBS formulation or a standard 1x PBS formulation that is explicitly and correctly scaled by 10.",
        "The answer clearly scopes the variant, such as standard PBS without Ca2+/Mg2+, unless another variant is explicitly requested.",
        "If gram amounts are given for phosphate salts, the exact salt identity and hydration state are supported by retrieval; otherwise the answer uses molar concentrations to avoid ambiguous masses."
      ]
    },
    {
      "criterion": "The answer is complete enough to satisfy the user's request",
      "evidence_required": [
        "The final recipe includes component identities and either masses for a stated final volume or molar concentrations.",
        "The final volume basis is explicit, such as per 1 L.",
        "The answer states the intended use of the stock, such as diluting 1:10 to make 1x PBS.",
        "Any pH target or pH-adjustment step is source-supported, or it is omitted rather than invented."
      ]
    }
  ],
  "continue_when": [
    {
      "criterion": "No real retrieval has been attempted",
      "reason": "Policy requires a retrieval attempt before answering."
    },
    {
      "criterion": "Only memory or an uncited recipe is available",
      "reason": "The loop should continue until the answer is grounded by retrieval or can be explicitly limitation-qualified after the attempt."
    },
    {
      "criterion": "The PBS variant is unresolved",
      "reason": "Sources conflict or are unclear about Ca2+/Mg2+ inclusion, phosphate split, or pH, and the answer does not clearly scope which standard is being used."
    },
    {
      "criterion": "The grams-based recipe is chemically ambiguous",
      "reason": "Phosphate salt identity or hydration state is unspecified, so the stated mass could be wrong even if the intended molarity is correct."
    },
    {
      "criterion": "Retrieved sources materially conflict",
      "reason": "If formulations disagree in a way that changes the actual recipe, continue until the answer can explain the difference or choose a clearly scoped standard."
    },
    {
      "criterion": "The draft answer adds unsupported procedural details",
      "reason": "Do not add sterilization, storage, or pH-adjustment specifics unless retrieval supports them or they are explicitly labeled as general lab practice rather than source-grounded fact."
    }
  ],
  "limitation_qualified_exit_when": [
    {
      "criterion": "Retrieval was attempted but no exact citation-backed 10x recipe was found",
      "required_evidence": [
        "A logged literature-search attempt exists.",
        "Retrieved evidence is insufficient for an exact grams-based 10x recipe, but sufficient to support a conventional PBS composition or a standard 1x PBS composition that is commonly scaled."
      ],
      "answer_requirements": [
        "State clearly that PBS formulations vary by source or vendor and that no exact source-backed 10x recipe was found in retrieval.",
        "Provide a typical formulation only if it is labeled as conventional and scoped, such as 'typical 10x PBS, no Ca2+/Mg2+'.",
        "Prefer molar concentrations or exact salt-form-qualified masses to reduce ambiguity.",
        "Tell the user to verify against their local SOP or vendor protocol if exact compatibility matters."
      ]
    },
    {
      "criterion": "Retrieved sources support the core composition but not every operational detail",
      "required_evidence": [
        "The composition is supported well enough to answer the core recipe question.",
        "Secondary details like sterile filtration, storage duration, or exact pH-adjustment procedure are missing or inconsistent."
      ],
      "answer_requirements": [
        "Answer the core recipe request.",
        "Mark unsupported operational details as unspecified rather than filling them in."
      ]
    }
  ],
  "do_not_block_exit_for": [
    "Lack of recent-only citations, because this is not a time-sensitive claim.",
    "Absence of multiple papers if one authoritative source or a clearly derivable standard formulation is sufficient.",
    "No web retrieval when web tools are not in scope and a literature-search attempt has already been made."
  ],
  "minimum_answer_elements_on_exit": [
    "Which PBS variant the recipe refers to",
    "Component identities",
    "Amounts or molarities tied to a final volume",
    "Whether the recipe is exact-source-backed or conventional-with-limitations",
    "A dilution statement from 10x to 1x"
  ]
}

